import{_ as o,o as r,c as i,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"A Solid case for NVMe. Jason Burris from Sony","description":"","frontmatter":{"title":"A Solid case for NVMe. Jason Burris from Sony","date":"2025-05-08T00:00:00.000Z","updated":"2025-05-08T00:00:00.000Z","tags":["Ceph","NVMe","SSD","Storage Performance","Hardware Upgrade"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/A_Solid_case_for_NVMe._Jason_Burris_from_Sony.md","filePath":"posts/2025/A_Solid_case_for_NVMe._Jason_Burris_from_Sony.md","lastUpdated":1780459816000}'),s={name:"posts/2025/A_Solid_case_for_NVMe._Jason_Burris_from_Sony.md"};function t(n,l,p,g,a,_){return r(),i("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要-从-hdd-到-nvme-的迁移及其对-ceph-集群的影响" tabindex="-1">会议纪要：从 HDD 到 NVMe 的迁移及其对 Ceph 集群的影响 <a class="header-anchor" href="#会议纪要-从-hdd-到-nvme-的迁移及其对-ceph-集群的影响" aria-label="Permalink to &quot;会议纪要：从 HDD 到 NVMe 的迁移及其对 Ceph 集群的影响&quot;">​</a></h3><p><strong>会议主题</strong>: 讨论从传统硬盘（HDD）迁移到固态硬盘（NVMe）的硬件升级及其对 Ceph 分布式存储系统的影响。</p><p><strong>主讲人</strong>: Stephie（索尼互动娱乐，存储团队产品负责人）</p><p><strong>会议内容概述</strong>:</p><ol><li><p><strong>背景介绍</strong>:</p><ul><li>Stephie 介绍了索尼互动娱乐的存储架构，主要使用 Ceph 作为后端存储系统，支持对象存储（S3）和块存储（RBD）。</li><li>当前集群中同时运行 HDD 和 NVMe 两种存储介质，讨论的重点是从 HDD 迁移到 NVMe 的时机和原因。</li></ul></li><li><p><strong>HDD 与 NVMe 的对比</strong>:</p><ul><li><strong>HDD</strong>: <ul><li>优点：容量大（最大 36TB），成本低。</li><li>缺点：延迟高（2ms），性能波动大，机械部件易损坏。</li></ul></li><li><strong>NVMe</strong>: <ul><li>优点：延迟低（微秒级），性能稳定，无机械部件。</li><li>缺点：成本高，容量相对较小（TLC 最大 16TB，QLC 最大 150TB），写入放大问题可能影响寿命。</li></ul></li></ul></li><li><p><strong>索尼的迁移历程</strong>:</p><ul><li><strong>第一代</strong>: 使用 1U 服务器，12 块 HDD + 4 块 SSD，SSD 用于日志和 DB。</li><li><strong>第二代</strong>: 增加 HDD 密度至 24 块，使用 NVMe 替代部分 SSD，部分配置为 RAID 1，部分直接分配给 OSD。</li><li><strong>第三代</strong>: 完全采用 NVMe，22 块 TLC NVMe，OSD 进程直接运行在 NVMe 上，简化了驱动更换和维护。</li></ul></li><li><p><strong>性能对比</strong>:</p><ul><li><strong>HDD</strong>: 读写延迟平均 50-70ms，但波动较大，尤其在数据恢复或回填时会出现明显的延迟峰值。</li><li><strong>NVMe</strong>: 读写延迟稳定在微秒级，波动极小，即使在数据恢复期间也不会对客户端造成明显影响。</li></ul></li><li><p><strong>实际使用情况</strong>:</p><ul><li>NVMe 的写入放大问题在实际使用中并不明显，TLC 和 QLC 的写入寿命远超预期，尤其是 QLC 在某些工作负载下表现出色。</li><li>实际生产环境中，NVMe 的写入寿命远未达到理论极限，99% 的企业 SSD 使用率不超过 15%。</li></ul></li><li><p><strong>未来硬件趋势</strong>:</p><ul><li><strong>EDSS 格式</strong>: 新的企业数据中心存储格式，优化了冷却和电源管理，支持更高的接口速度（如 PCIe 5.0 及以上）。</li><li><strong>ZNS（分区命名空间）</strong>: 允许应用程序直接在驱动器上管理命名空间，减少写入放大，提升性能。</li><li><strong>Ceph 的改进</strong>: Ceph 正在为高速存储设备（如 NVMe）进行优化，未来可能会更好地利用这些硬件的潜力。</li></ul></li><li><p><strong>迁移的考虑因素</strong>:</p><ul><li><strong>性能提升</strong>: NVMe 在数据恢复和回填操作中表现优异，减少了客户端的延迟和中断。</li><li><strong>运维简化</strong>: NVMe 的自包含设计减少了驱动更换的复杂性，自动化程度更高。</li><li><strong>成本与 ROI</strong>: 虽然 NVMe 初始成本较高，但长期来看，由于性能提升和运维简化，总体成本可能更低。</li></ul></li><li><p><strong>未来展望</strong>:</p><ul><li>索尼选择 NVMe 不仅是为了当前的性能需求，也是为了未来硬件的兼容性，避免频繁的硬件刷新。</li><li>随着硬件技术的进步，NVMe 的性能和容量将继续提升，Ceph 也将进一步优化以充分利用这些硬件。</li></ul></li></ol><p><strong>决定事项</strong>:</p><ul><li>继续推进 NVMe 的部署，逐步淘汰旧的 HDD 集群。</li><li>持续监控 NVMe 的实际使用情况，特别是写入放大和寿命问题。</li><li>关注未来硬件技术的发展，特别是 EDSS 格式和 ZNS 技术的应用。</li></ul><p><strong>后续行动计划</strong>:</p><ul><li>完成现有 HDD 集群的迁移，确保数据平稳过渡。</li><li>优化 Ceph 配置，进一步挖掘 NVMe 的性能潜力。</li><li>与硬件供应商保持沟通，了解最新的存储技术进展。</li></ul><p><strong>总结</strong>: 本次会议详细讨论了从 HDD 到 NVMe 的迁移过程及其对 Ceph 集群的影响，展示了 NVMe 在性能、稳定性和运维简化方面的优势。未来，随着硬件技术的进步，Ceph 集群的性能和可靠性将进一步提升。</p>',10)])])}const S=o(s,[["render",t]]);export{u as __pageData,S as default};
